private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
    String degreeStr = degreeText.getText().toString().trim();

    if (degreeStr.isEmpty()) {
        // Nothing was entered, keep on showing the value the arc is currently set to.
        degree = arcProgressToDegree(seekArc.getProgress());
    } else {
        try {
            degree = Integer.parseInt(degreeStr);
        } catch (NumberFormatException e) {
            resetServo(degreeText, seekArc);
            toastInvalidValueMessage();
            return;
        }
    }

    if (degree > 360 || degree < 0) {
        resetServo(degreeText, seekArc);
        toastInvalidValueMessage();
    } else {
        // The arc can only be positioned in steps of DEGREES_PER_PROGRESS_STEP, so moving it
        // to the entered value fires onProgressChanged() with a rounded progress value.
        // The flag has to be raised before updating the arc, otherwise the listener would
        // overwrite the value entered by the user with the rounded one.
        editEnter = true;
        seekArc.setProgress((int) Math.round(degree / DEGREES_PER_PROGRESS_STEP));
        // Make sure the entered value is shown, even if the listener was not invoked.
        degreeText.setText(String.valueOf(degree));
        degreeText.setCursorVisible(false);
        editEnter = false;
    }
}

