// Mirrors SeekArc v1.1 (max=100, sweep=360): setProgress -> listener fires synchronously,
// drag progress = round(touchAngle * max/sweep).
public class Sim {
    interface Listener { void onProgressChanged(int progress); }
    static class SeekArc {
        int max = 100, progress; Listener l;
        void setProgress(int p) { if (l != null) l.onProgressChanged(p);
            p = Math.min(Math.max(p, 0), max); progress = p; }
        int getProgress() { return progress; }
        void drag(double angle) { setProgress((int) Math.round(angle * max / 360.0)); }
    }
    static final double DEGREES_PER_PROGRESS_STEP = 3.6;
    static int degree; static boolean editEnter = false;
    static String text = "0"; static Integer tag = null;

    static int arcProgressToDegree(int p) { return (int) (p * DEGREES_PER_PROGRESS_STEP); }
    static void updateDegreeText(int arcProgress) {
        if (editEnter) { text = String.valueOf(degree); }
        else { int d = arcProgressToDegree(arcProgress); text = String.valueOf(d); tag = d; }
    }
    static void processDegreeInput(SeekArc arc) {
        String s = text.trim();
        if (s.isEmpty()) degree = (tag != null) ? tag : arcProgressToDegree(arc.getProgress());
        else degree = Integer.parseInt(s);
        if (degree > 360 || degree < 0) { degree = 0; editEnter = true; arc.setProgress(0);
            text = "0"; tag = 0; editEnter = false; }
        else { editEnter = true; arc.setProgress((int) Math.round(degree / DEGREES_PER_PROGRESS_STEP));
            text = String.valueOf(degree); tag = degree; editEnter = false; }
    }
    public static void main(String[] a) {
        SeekArc arc = new SeekArc(); arc.l = p -> updateDegreeText(p);
        // Repro: drag to 100, then type 38 + Enter
        arc.drag(100.0); System.out.println("after drag  -> displayed=" + text + " progress=" + arc.getProgress());
        text = "38"; processDegreeInput(arc);
        System.out.println("after enter 38 -> displayed=" + text + "  (expected 38)");
        // Next drag must still follow the arc (flag not left dangling)
        arc.drag(200.0); System.out.println("after drag  -> displayed=" + text);
        // Typing again right after a drag
        text = "38"; processDegreeInput(arc); System.out.println("enter 38 again -> " + text);
        // Same rounded progress as current: 39 -> progress 11 (unchanged) : listener may not differ
        text = "39"; processDegreeInput(arc); System.out.println("enter 39 -> " + text + " (expected 39)");
        // Empty input keeps previous value
        text = ""; processDegreeInput(arc); System.out.println("enter empty -> " + text + " (expected 39)");
        // Boundary values
        for (String v : new String[]{"0", "360", "1", "359"}) {
            text = v; processDegreeInput(arc);
            System.out.println("enter " + v + " -> " + text + (text.equals(v) ? " OK" : " FAIL"));
        }
    }
}
